/****************************************************************************
 * vendor/artinchip/chips/d13x/artinchip_dsi.c
 *
 * D13x MIPI DSI 控制器驱动
 * 参考: luban-lite aic_hal_dsi.c
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <debug.h>
#include "chip.h"
#include "artinchip_dsi.h"

/* 位操作宏 */

#ifndef BIT
#define BIT(nr)         (1UL << (nr))
#endif

#ifndef GENMASK
#define GENMASK(h, l)   (((0xFFFFFFFFUL) << (l)) & (0xFFFFFFFFUL >> (31UL - (h))))
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* MIPI DSI 寄存器偏移 (来源: luban-lite aic_hal_dsi.h) */

#define DSI_CTL                 0x00
#define DSI_CLK_CFG             0x04
#define DSI_DPI_IN_POL          0x10
#define DSI_DPI_IN_FMT          0x14
#define DSI_DPI_VC              0x18
#define DSI_DPI_LPTX_TIME       0x1C
#define DSI_VID_MODE_CFG        0x30
#define DSI_VID_PKG_SIZE        0x34
#define DSI_VID_HINACT_TIME     0x40
#define DSI_VID_HT_TIME         0x44
#define DSI_VID_VBLANK_LINE     0x48
#define DSI_VID_VACT_LINE       0x4C
#define DSI_CMD_MODE_CFG        0x50
#define DSI_TO_CNT_CFG          0x70
#define DSI_PHY_CFG             0x80
#define DSI_PHY_STA             0x84
#define DSI_PHY_CLK_TIME        0x88
#define DSI_PHY_DATA_TIME       0x8C
#define DSI_PHY_RD_TIME         0x90
#define DSI_PHY_TEST1           0xC0
#define DSI_PHY_TEST2           0xC4
#define DSI_DPI_IF_CFG          0x400
#define DSI_LANE_CFG            0x410
#define DSI_ANA_CFG1            0x500
#define DSI_ANA_CFG2            0x504
#define DSI_GEN_PD_CFG         0x200
#define DSI_EDPI_CMD_SIZE       0x1C0
#define DSI_VID_CHK_NUM         0x38
#define DSI_VID_NULL_SIZE       0x3C

/* CTL 位域 */

#define DSI_CTL_EN              BIT(0)
#define DSI_CTL_DSI_MODE        BIT(1)
#define DSI_CTL_PKG_CFG_CRC_RX_EN   BIT(7)
#define DSI_CTL_PKG_CFG_ECC_RX_EN   BIT(6)
#define DSI_CTL_PKG_CFG_BTA_EN      BIT(5)

/* PHY_CFG 位域 */

#define DSI_PHY_CFG_RST_SHUTDOWNZ   BIT(4)
#define DSI_PHY_CFG_RST_RSTN        BIT(5)
#define DSI_PHY_CFG_RST_CLK_EN      BIT(6)
#define DSI_PHY_CFG_HSCLK_REQ       BIT(2)
#define DSI_PHY_CFG_LP11_TIME_MASK  GENMASK(15, 8)
#define DSI_PHY_CFG_LP11_TIME(x)    (((x) & 0xFF) << 8)
#define DSI_PHY_CFG_DATA_LANE_MASK  GENMASK(1, 0)
#define DSI_PHY_CFG_DATA_LANE(x)    (((x) & 0x3) << 0)

/* PHY_STA 位域 */

#define DSI_PHY_STA_STOP_STATE_C    BIT(2)
#define DSI_PHY_STA_STOP_STATE_0    BIT(3)
#define DSI_PHY_STA_PHY_LOCK        BIT(0)

/* ANA_CFG2 位域 */

#define DSI_ANA_CFG2_EN_BIAS        BIT(0)
#define DSI_ANA_CFG2_EN_VP_MASK     GENMASK(2, 1)
#define DSI_ANA_CFG2_EN_VP(x)       (((x) & 0x3) << 1)
#define DSI_ANA_CFG2_EN_LDO_MASK    GENMASK(7, 3)
#define DSI_ANA_CFG2_EN_LDO(x)      (((x) & 0x1F) << 3)
#define DSI_ANA_CFG2_EN_RESCAL      BIT(8)
#define DSI_ANA_CFG2_ON_RESCAL      BIT(9)
#define DSI_ANA_CFG2_RCAL_FLAG      BIT(10)
#define DSI_ANA_CFG2_EN_CLK         BIT(12)

/* CLK_CFG 位域 */

#define DSI_CLK_CFG_LP_DIV_MASK     GENMASK(7, 0)
#define DSI_CLK_CFG_LP_DIV(x)       (((x) & 0xFF) << 0)

/* DPI_IN_POL 位域 */

#define DSI_DPI_IN_POL_DE           BIT(0)
#define DSI_DPI_IN_POL_VSYNC        BIT(1)
#define DSI_DPI_IN_POL_HSYNC        BIT(2)
#define DSI_DPI_IN_POL_SHUTDOWN     BIT(3)
#define DSI_DPI_IN_POL_COLORM       BIT(4)

/* DPI_IN_FMT 位域 */

#define DSI_DPI_IN_FMT_DT_MASK      GENMASK(7, 4)
#define DSI_DPI_IN_FMT_DT(x)        (((x) & 0xF) << 4)
#define DSI_DPI_IN_FMT_LOOSELY18    BIT(8)

/* DPI_IF_CFG 位域 */

#define DSI_DPI_IF_CFG_FMT_MASK     GENMASK(5, 4)
#define DSI_DPI_IF_CFG_FMT(x)       (((x) & 0x3) << 4)
#define DSI_DPI_IF_CFG_SHUTD        BIT(16)
#define DSI_DPI_IF_CFG_COLORM       BIT(17)

/* DPI_VC 位域 */

#define DSI_DPI_VC_NUM_MASK         GENMASK(1, 0)
#define DSI_DPI_VC_NUM(x)           (((x) & 0x3) << 0)

/* VID_MODE_CFG 位域 */

#define DSI_VID_MODE_CFG_TYPE_MASK  GENMASK(1, 0)
#define DSI_VID_MODE_CFG_TYPE(x)    (((x) & 0x3) << 0)
#define DSI_VID_MODE_CFG_LP_EN_VSA  BIT(8)
#define DSI_VID_MODE_CFG_LP_EN_VBP  BIT(9)
#define DSI_VID_MODE_CFG_LP_EN_VFP  BIT(10)
#define DSI_VID_MODE_CFG_LP_EN_VACT BIT(11)
#define DSI_VID_MODE_CFG_LP_EN_HBP  BIT(12)
#define DSI_VID_MODE_CFG_LP_EN_HFP  BIT(13)
#define DSI_VID_MODE_CFG_FRAME_BTA_ACK_EN BIT(14)
#define DSI_VID_MODE_CFG_CMD_LPTX_FORCE BIT(16)

/* VID_HINACT_TIME 位域 */

#define DSI_VID_HSA_TIME_MASK       GENMASK(15, 0)
#define DSI_VID_HSA_TIME(x)         (((x) & 0xFFFF) << 0)
#define DSI_VID_HBP_TIME_MASK       GENMASK(31, 16)
#define DSI_VID_HBP_TIME(x)         (((x) & 0xFFFF) << 16)

/* VID_VACT_LINE 位域 */

#define DSI_VID_VSA_LINE_MASK       GENMASK(15, 0)
#define DSI_VID_VSA_LINE(x)         (((x) & 0xFFFF) << 0)
#define DSI_VID_VACT_TIME_MASK      GENMASK(31, 16)
#define DSI_VID_VACT_TIME(x)        (((x) & 0xFFFF) << 16)

/* VID_VBLANK_LINE 位域 */

#define DSI_VID_VBP_TIME_MASK       GENMASK(15, 0)
#define DSI_VID_VBP_TIME(x)         (((x) & 0xFFFF) << 0)
#define DSI_VID_VFP_LINE_MASK       GENMASK(31, 16)
#define DSI_VID_VFP_LINE(x)         (((x) & 0xFFFF) << 16)

/* CMD_MODE_CFG 位域 */

#define DSI_CMD_MODE_CFG_GEN_SW_0P  BIT(0)
#define DSI_CMD_MODE_CFG_GEN_SW_1P  BIT(1)
#define DSI_CMD_MODE_CFG_GEN_SW_2P  BIT(2)
#define DSI_CMD_MODE_CFG_GEN_SR_0P  BIT(3)
#define DSI_CMD_MODE_CFG_GEN_SR_1P  BIT(4)
#define DSI_CMD_MODE_CFG_GEN_SR_2P  BIT(5)
#define DSI_CMD_MODE_CFG_GEN_LW     BIT(6)
#define DSI_CMD_MODE_CFG_DCS_SW_0P  BIT(8)
#define DSI_CMD_MODE_CFG_DCS_SW_1P  BIT(9)
#define DSI_CMD_MODE_CFG_DCS_SR_0P  BIT(10)
#define DSI_CMD_MODE_CFG_DCS_LW     BIT(11)
#define DSI_CMD_MODE_CFG_ACK_REQ_EN BIT(24)
#define DSI_CMD_MODE_CFG_TE_EN      BIT(16)

/* DSI 数据类型 */

#define DSI_DT_GEN_WR_P0   0x03
#define DSI_DT_GEN_WR_P1   0x13
#define DSI_DT_GEN_WR_P2   0x23
#define DSI_DT_GEN_RD_P0   0x04
#define DSI_DT_GEN_RD_P1   0x14
#define DSI_DT_GEN_RD_P2   0x24
#define DSI_DT_GEN_LONG_WR 0x29
#define DSI_DT_DCS_WR_P0   0x05
#define DSI_DT_DCS_WR_P1   0x15
#define DSI_DT_DCS_RD_P0   0x06
#define DSI_DT_DCS_LONG_WR 0x39

/* DSI 模式 */

#define DSI_MOD_VID_SYNC_PULSES  0
#define DSI_MOD_VID_SYNC_EVENT   1
#define DSI_MOD_VID_BURST        2
#define DSI_MOD_CMD_MODE         3

/* DSI 格式 */

#define DSI_FMT_RGB888    0
#define DSI_FMT_RGB666    1
#define DSI_FMT_RGB666L   2
#define DSI_FMT_RGB565    3
#define DSI_FMT_MAX       4

/* 默认配置 */

#define DSI_LP_RATE                 (10 * 1000 * 1000)  /* 10MHz */
#define DSI_LANE_NUM                4
#define DSI_TIMEOUT_US              1000000

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static inline void dsi_write(uint32_t offset, uint32_t value)
{
  putreg32(value, D13X_MIPI_DSI_BASE + offset);
}

static inline uint32_t dsi_read(uint32_t offset)
{
  return getreg32(D13X_MIPI_DSI_BASE + offset);
}

static inline void dsi_set_bits(uint32_t offset, uint32_t bits)
{
  uint32_t val = dsi_read(offset);
  val |= bits;
  dsi_write(offset, val);
}

static inline void dsi_clr_bits(uint32_t offset, uint32_t bits)
{
  uint32_t val = dsi_read(offset);
  val &= ~bits;
  dsi_write(offset, val);
}

static inline void dsi_set_bits_msk(uint32_t offset, uint32_t mask, uint32_t bits)
{
  uint32_t val = dsi_read(offset);
  val &= ~mask;
  val |= bits;
  dsi_write(offset, val);
}

static int dsi_wait_stop_state_c(void)
{
  uint32_t timeout = DSI_TIMEOUT_US;

  while (!(dsi_read(DSI_PHY_STA) & DSI_PHY_STA_STOP_STATE_C))
    {
      if (--timeout == 0)
        {
          ierr("DSI: Timeout waiting for stop state C\n");
          return -ETIMEDOUT;
        }
      up_udelay(1);
    }

  return OK;
}

/****************************************************************************
 * Name: dsi_dphy_cfg_hsfreq
 *
 * Description:
 *   配置 PHY HS 频率 (来源: luban-lite aic_hal_dsi.c)
 *
 ****************************************************************************/

static void dsi_dphy_cfg_hsfreq(uint32_t sclk_mhz)
{
  uint32_t freq_wdata;

  if (sclk_mhz >= 80 && sclk_mhz <= 89)
    {
      freq_wdata = 0x00 << 1;
    }
  else if (sclk_mhz >= 90 && sclk_mhz <= 99)
    {
      freq_wdata = 0x10 << 1;
    }
  else if (sclk_mhz >= 100 && sclk_mhz <= 109)
    {
      freq_wdata = 0x20 << 1;
    }
  else if (sclk_mhz >= 110 && sclk_mhz <= 129)
    {
      freq_wdata = 0x01 << 1;
    }
  else if (sclk_mhz >= 130 && sclk_mhz <= 139)
    {
      freq_wdata = 0x11 << 1;
    }
  else if (sclk_mhz >= 140 && sclk_mhz <= 149)
    {
      freq_wdata = 0x21 << 1;
    }
  else if (sclk_mhz >= 150 && sclk_mhz <= 169)
    {
      freq_wdata = 0x02 << 1;
    }
  else if (sclk_mhz >= 170 && sclk_mhz <= 179)
    {
      freq_wdata = 0x12 << 1;
    }
  else if (sclk_mhz >= 180 && sclk_mhz <= 199)
    {
      freq_wdata = 0x22 << 1;
    }
  else if (sclk_mhz >= 200 && sclk_mhz <= 219)
    {
      freq_wdata = 0x03 << 1;
    }
  else if (sclk_mhz >= 220 && sclk_mhz <= 239)
    {
      freq_wdata = 0x13 << 1;
    }
  else if (sclk_mhz >= 240 && sclk_mhz <= 249)
    {
      freq_wdata = 0x23 << 1;
    }
  else if (sclk_mhz >= 250 && sclk_mhz <= 269)
    {
      freq_wdata = 0x04 << 1;
    }
  else if (sclk_mhz >= 270 && sclk_mhz <= 299)
    {
      freq_wdata = 0x14 << 1;
    }
  else if (sclk_mhz >= 300 && sclk_mhz <= 329)
    {
      freq_wdata = 0x05 << 1;
    }
  else if (sclk_mhz >= 330 && sclk_mhz <= 359)
    {
      freq_wdata = 0x15 << 1;
    }
  else if (sclk_mhz >= 360 && sclk_mhz <= 399)
    {
      freq_wdata = 0x25 << 1;
    }
  else if (sclk_mhz >= 400 && sclk_mhz <= 449)
    {
      freq_wdata = 0x06 << 1;
    }
  else if (sclk_mhz >= 450 && sclk_mhz <= 499)
    {
      freq_wdata = 0x16 << 1;
    }
  else if (sclk_mhz >= 500 && sclk_mhz <= 549)
    {
      freq_wdata = 0x07 << 1;
    }
  else if (sclk_mhz >= 550 && sclk_mhz <= 599)
    {
      freq_wdata = 0x17 << 1;
    }
  else if (sclk_mhz >= 600 && sclk_mhz <= 649)
    {
      freq_wdata = 0x08 << 1;
    }
  else if (sclk_mhz >= 650 && sclk_mhz <= 699)
    {
      freq_wdata = 0x18 << 1;
    }
  else if (sclk_mhz >= 700 && sclk_mhz <= 749)
    {
      freq_wdata = 0x09 << 1;
    }
  else if (sclk_mhz >= 750 && sclk_mhz <= 799)
    {
      freq_wdata = 0x19 << 1;
    }
  else if (sclk_mhz >= 800 && sclk_mhz <= 849)
    {
      freq_wdata = 0x29 << 1;
    }
  else if (sclk_mhz >= 850 && sclk_mhz <= 899)
    {
      freq_wdata = 0x39 << 1;
    }
  else if (sclk_mhz >= 900 && sclk_mhz <= 949)
    {
      freq_wdata = 0x0a << 1;
    }
  else if (sclk_mhz >= 950 && sclk_mhz <= 999)
    {
      freq_wdata = 0x1a << 1;
    }
  else if (sclk_mhz >= 1000 && sclk_mhz <= 1049)
    {
      freq_wdata = 0x2a << 1;
    }
  else if (sclk_mhz >= 1050 && sclk_mhz <= 1099)
    {
      freq_wdata = 0x3a << 1;
    }
  else if (sclk_mhz >= 1100 && sclk_mhz <= 1149)
    {
      freq_wdata = 0x0b << 1;
    }
  else if (sclk_mhz >= 1150 && sclk_mhz <= 1199)
    {
      freq_wdata = 0x1b << 1;
    }
  else if (sclk_mhz >= 1200 && sclk_mhz <= 1249)
    {
      freq_wdata = 0x2b << 1;
    }
  else if (sclk_mhz >= 1250 && sclk_mhz <= 1299)
    {
      freq_wdata = 0x3b << 1;
    }
  else if (sclk_mhz >= 1300 && sclk_mhz <= 1349)
    {
      freq_wdata = 0x0c << 1;
    }
  else if (sclk_mhz >= 1350 && sclk_mhz <= 1399)
    {
      freq_wdata = 0x1c << 1;
    }
  else if (sclk_mhz >= 1400 && sclk_mhz <= 1449)
    {
      freq_wdata = 0x2c << 1;
    }
  else if (sclk_mhz >= 1450 && sclk_mhz <= 1499)
    {
      freq_wdata = 0x3c << 1;
    }
  else
    {
      freq_wdata = 0x00;
    }

  /* 通过 PHY_TEST1/TEST2 接口配置 HS 频率
   * 寄存器 0x44 = HS frequency code
   */

  dsi_write(DSI_PHY_TEST2, 0x00);
  dsi_write(DSI_PHY_TEST1, (0x44 << 8) | freq_wdata);
  dsi_set_bits(DSI_PHY_TEST1, BIT(0));  /* Write enable */
  up_udelay(1);
  dsi_clr_bits(DSI_PHY_TEST1, BIT(0));  /* Clear write enable */
  up_udelay(1);
}

/****************************************************************************
 * Name: d13x_dsi_enable
 *
 * Description:
 *   使能 MIPI DSI 控制器
 *
 ****************************************************************************/

void d13x_dsi_enable(void)
{
  dsi_set_bits(DSI_CTL, DSI_CTL_EN);
}

/****************************************************************************
 * Name: d13x_dsi_disable
 *
 * Description:
 *   禁用 MIPI DSI 控制器
 *
 ****************************************************************************/

void d13x_dsi_disable(void)
{
  dsi_clr_bits(DSI_CTL, DSI_CTL_EN);
}

/****************************************************************************
 * Name: d13x_dsi_phy_init
 *
 * Description:
 *   初始化 MIPI DSI PHY (参考: luban-lite aic_hal_dsi.c)
 *
 ****************************************************************************/

int d13x_dsi_phy_init(uint32_t pixel_clock)
{
  uint32_t val;
  uint32_t timeout;
  uint32_t sclk_mhz;

  /* PHY 时序配置 */

  dsi_write(DSI_PHY_RD_TIME, 50);
  dsi_set_bits_msk(DSI_PHY_CLK_TIME,
    (0x3FF << 16) | 0x3FF,
    (20 << 16) | 20);  /* HS2LP=20, LP2HS=20 */
  dsi_set_bits_msk(DSI_PHY_DATA_TIME,
    (0x3FF << 16) | 0x3FF,
    (20 << 16) | 20);

  /* 模拟配置 */

  dsi_set_bits(DSI_ANA_CFG2, DSI_ANA_CFG2_EN_BIAS);
  up_udelay(5);

  val = dsi_read(DSI_ANA_CFG2);
  val &= ~DSI_ANA_CFG2_EN_VP_MASK;
  val |= DSI_ANA_CFG2_EN_VP(3);
  val &= ~DSI_ANA_CFG2_EN_LDO_MASK;
  val |= DSI_ANA_CFG2_EN_LDO(0x1F);
  dsi_write(DSI_ANA_CFG2, val);
  up_udelay(10);

  /* 校准 */

  dsi_set_bits(DSI_ANA_CFG2, DSI_ANA_CFG2_EN_RESCAL);
  dsi_set_bits(DSI_ANA_CFG2, DSI_ANA_CFG2_ON_RESCAL);

  /* 等待校准完成 */

  timeout = DSI_TIMEOUT_US;
  while (!(dsi_read(DSI_ANA_CFG2) & DSI_ANA_CFG2_RCAL_FLAG))
    {
      if (--timeout == 0)
        {
          ierr("DSI: Timeout waiting for RCAL flag\n");
          return -ETIMEDOUT;
        }
      up_udelay(1);
    }

  /* 使能时钟 */

  dsi_set_bits(DSI_ANA_CFG2, DSI_ANA_CFG2_EN_CLK);

  /* PHY 复位序列 */

  dsi_set_bits(DSI_PHY_TEST1, BIT(0));  /* CLR */
  up_udelay(5);

  dsi_clr_bits(DSI_PHY_CFG, DSI_PHY_CFG_RST_RSTN);
  up_udelay(5);

  dsi_clr_bits(DSI_PHY_CFG, DSI_PHY_CFG_RST_SHUTDOWNZ);
  up_udelay(5);

  dsi_clr_bits(DSI_PHY_TEST1, BIT(0));  /* Clear CLR */
  up_udelay(5);

  /* 配置 HS 频率 (来源: luban-lite dsi_dphy_cfg_hsfreq) */

  /* sclk = pixel_clock * 24 / 4 = pixel_clock * 6
   * sclk_mhz = sclk / 1000000
   */

  sclk_mhz = (pixel_clock * 6) / 1000000;
  dsi_dphy_cfg_hsfreq(sclk_mhz);

  /* 启动 PHY */

  dsi_set_bits(DSI_PHY_CFG, DSI_PHY_CFG_RST_SHUTDOWNZ);
  up_udelay(5);

  dsi_set_bits(DSI_PHY_CFG, DSI_PHY_CFG_RST_RSTN);
  up_udelay(5);

  /* 配置 LP11时间和数据通道 */

  val = dsi_read(DSI_PHY_CFG);
  val &= ~DSI_PHY_CFG_LP11_TIME_MASK;
  val |= DSI_PHY_CFG_LP11_TIME(10);
  val &= ~DSI_PHY_CFG_DATA_LANE_MASK;
  val |= DSI_PHY_CFG_DATA_LANE(DSI_LANE_NUM - 1);
  dsi_write(DSI_PHY_CFG, val);
  up_udelay(5);

  /* 使能时钟 */

  dsi_set_bits(DSI_PHY_CFG, DSI_PHY_CFG_RST_CLK_EN);

  iinfo("DSI PHY initialized, sclk=%dMHz\n", sclk_mhz);
  return OK;
}

/****************************************************************************
 * Name: d13x_dsi_hs_clk_enable
 *
 * Description:
 *   使能/禁用 DSI 高速时钟
 *
 ****************************************************************************/

int d13x_dsi_hs_clk_enable(bool enable)
{
  int ret;

  if (enable)
    {
      ret = dsi_wait_stop_state_c();
      if (ret < 0)
        {
          return ret;
        }

      dsi_set_bits(DSI_PHY_CFG, DSI_PHY_CFG_HSCLK_REQ);
    }
  else
    {
      dsi_clr_bits(DSI_PHY_CFG, DSI_PHY_CFG_HSCLK_REQ);
    }

  return OK;
}

/****************************************************************************
 * Name: d13x_dsi_set_vm
 *
 * Description:
 *   配置 DSI 视频模式 (来源: luban-lite aic_hal_dsi.c)
 *
 ****************************************************************************/

void d13x_dsi_set_vm(uint32_t hactive, uint32_t vactive,
                     uint32_t hfp, uint32_t hbp, uint32_t hsync,
                     uint32_t vfp, uint32_t vbp, uint32_t vsync)
{
  uint32_t if_cfg_fmt[] = {0, 0, 1, 2};
  uint32_t in_fmt_dt[] = {5, 3, 3, 1};
  uint32_t dsi_bits_per_pixel[] = {24, 24, 18, 16};
  uint32_t format = DSI_FMT_RGB888;
  uint32_t mode = DSI_MOD_VID_BURST;
  uint32_t vc = 0;
  uint32_t ht = hbp + hsync + hactive + hfp;
  uint32_t lane = DSI_LANE_NUM;

  /* 配置 DPI 接口 */

  dsi_clr_bits(DSI_DPI_IF_CFG, DSI_DPI_IF_CFG_SHUTD | DSI_DPI_IF_CFG_COLORM);
  dsi_set_bits_msk(DSI_DPI_IF_CFG, DSI_DPI_IF_CFG_FMT_MASK,
    DSI_DPI_IF_CFG_FMT(if_cfg_fmt[format]));

  /* 配置输入格式 */

  dsi_set_bits_msk(DSI_DPI_IN_FMT, DSI_DPI_IN_FMT_DT_MASK,
    DSI_DPI_IN_FMT_DT(in_fmt_dt[format]));
  dsi_clr_bits(DSI_DPI_IN_FMT, DSI_DPI_IN_FMT_LOOSELY18);

  /* 配置 VC */

  dsi_set_bits_msk(DSI_DPI_VC, DSI_DPI_VC_NUM_MASK, DSI_DPI_VC_NUM(vc));

  /* 配置极性 */

  dsi_clr_bits(DSI_DPI_IN_POL, DSI_DPI_IN_POL_DE);
  dsi_set_bits(DSI_DPI_IN_POL, DSI_DPI_IN_POL_VSYNC);
  dsi_set_bits(DSI_DPI_IN_POL, DSI_DPI_IN_POL_HSYNC);
  dsi_clr_bits(DSI_DPI_IN_POL, DSI_DPI_IN_POL_SHUTDOWN | DSI_DPI_IN_POL_COLORM);

  /* 配置视频模式 */

  dsi_clr_bits(DSI_CTL, DSI_CTL_DSI_MODE);

  dsi_set_bits_msk(DSI_VID_MODE_CFG, DSI_VID_MODE_CFG_TYPE_MASK,
    DSI_VID_MODE_CFG_TYPE(mode));
  dsi_set_bits(DSI_VID_MODE_CFG,
    DSI_VID_MODE_CFG_LP_EN_VSA | DSI_VID_MODE_CFG_LP_EN_VBP |
    DSI_VID_MODE_CFG_LP_EN_VFP | DSI_VID_MODE_CFG_LP_EN_VACT |
    DSI_VID_MODE_CFG_LP_EN_HBP);
  dsi_set_bits(DSI_VID_MODE_CFG, DSI_VID_MODE_CFG_LP_EN_HFP);
  dsi_clr_bits(DSI_VID_MODE_CFG, DSI_VID_MODE_CFG_FRAME_BTA_ACK_EN);
  dsi_set_bits(DSI_VID_MODE_CFG, DSI_VID_MODE_CFG_CMD_LPTX_FORCE);

  /* 配置包大小 */

  dsi_write(DSI_VID_PKG_SIZE, hactive);
  dsi_write(DSI_VID_CHK_NUM, 1);
  dsi_write(DSI_VID_NULL_SIZE, 0);

  /* 配置水平时序 */

  dsi_set_bits_msk(DSI_VID_HINACT_TIME, DSI_VID_HSA_TIME_MASK,
    DSI_VID_HSA_TIME(hsync * dsi_bits_per_pixel[format] / (8 * lane)));
  dsi_set_bits_msk(DSI_VID_HINACT_TIME, DSI_VID_HBP_TIME_MASK,
    DSI_VID_HBP_TIME(hbp * dsi_bits_per_pixel[format] / (8 * lane)));

  dsi_write(DSI_VID_HT_TIME,
    ht * dsi_bits_per_pixel[format] / (8 * lane));

  /* 配置垂直时序 */

  dsi_set_bits_msk(DSI_VID_VACT_LINE, DSI_VID_VSA_LINE_MASK,
    DSI_VID_VSA_LINE(vsync));
  dsi_set_bits_msk(DSI_VID_VACT_LINE, DSI_VID_VACT_TIME_MASK,
    DSI_VID_VACT_TIME(vactive));

  dsi_set_bits_msk(DSI_VID_VBLANK_LINE, DSI_VID_VBP_TIME_MASK,
    DSI_VID_VBP_TIME(vbp));
  dsi_set_bits_msk(DSI_VID_VBLANK_LINE, DSI_VID_VFP_LINE_MASK,
    DSI_VID_VFP_LINE(vfp));

  iinfo("DSI VM: %dx%d, hfp=%d hbp=%d hsync=%d vfp=%d vbp=%d vsync=%d\n",
        hactive, vactive, hfp, hbp, hsync, vfp, vbp, vsync);
}

/****************************************************************************
 * Name: d13x_dsi_cmd_wr
 *
 * Description:
 *   发送 DSI 命令 (来源: luban-lite aic_hal_dsi.c)
 *
 ****************************************************************************/

int d13x_dsi_cmd_wr(uint32_t dt, const uint8_t *data, uint32_t len)
{
  const uint8_t *p = data;
  uint8_t d0, d1, i;
  uint32_t val;
  int ret;

  /* 确定数据类型参数 */

  switch (dt)
    {
      case DSI_DT_GEN_WR_P0:
      case DSI_DT_GEN_RD_P0:
        d0 = 0; d1 = 0; i = 0;
        break;
      case DSI_DT_GEN_WR_P1:
      case DSI_DT_GEN_RD_P1:
      case DSI_DT_DCS_WR_P0:
      case DSI_DT_DCS_RD_P0:
        d0 = *p++; d1 = 0; i = 1;
        break;
      case DSI_DT_GEN_WR_P2:
      case DSI_DT_GEN_RD_P2:
      case DSI_DT_DCS_WR_P1:
        d0 = *p++; d1 = *p++; i = 2;
        break;
      case DSI_DT_GEN_LONG_WR:
      case DSI_DT_DCS_LONG_WR:
        d0 = len >> 0; d1 = (len >> 8) & 0xff; i = 0;
        break;
      default:
        d0 = 0; d1 = 0; i = 0;
        break;
    }

  /* 配置命令模式 */

  switch (dt)
    {
      case DSI_DT_GEN_WR_P0:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_GEN_SW_0P);
        break;
      case DSI_DT_GEN_WR_P1:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_GEN_SW_1P);
        break;
      case DSI_DT_GEN_WR_P2:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_GEN_SW_2P);
        break;
      case DSI_DT_GEN_RD_P0:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_GEN_SR_0P);
        break;
      case DSI_DT_GEN_RD_P1:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_GEN_SR_1P);
        break;
      case DSI_DT_GEN_RD_P2:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_GEN_SR_2P);
        break;
      case DSI_DT_GEN_LONG_WR:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_GEN_LW);
        break;
      case DSI_DT_DCS_WR_P0:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_DCS_SW_0P);
        break;
      case DSI_DT_DCS_WR_P1:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_DCS_SW_1P);
        break;
      case DSI_DT_DCS_RD_P0:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_DCS_SR_0P);
        break;
      case DSI_DT_DCS_LONG_WR:
        dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_DCS_LW);
        break;
    }

  /* 配置 BTA */

  if (dt == DSI_DT_GEN_RD_P0 || dt == DSI_DT_GEN_RD_P1 ||
      dt == DSI_DT_GEN_RD_P2 || dt == DSI_DT_DCS_RD_P0)
    {
      dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_ACK_REQ_EN);
      dsi_set_bits(DSI_CTL, DSI_CTL_PKG_CFG_BTA_EN);
    }
  else
    {
      dsi_clr_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_ACK_REQ_EN);
      dsi_clr_bits(DSI_CTL, DSI_CTL_PKG_CFG_BTA_EN);
    }

  /* 写入数据到 GEN_PD_CFG */

  for (; i < len; i += 4)
    {
      uint32_t payload = 0;
      if (i < len)
        payload |= *(p + i);
      if (i + 1 < len)
        payload |= (*(p + i + 1) << 8);
      if (i + 2 < len)
        payload |= (*(p + i + 2) << 16);
      if (i + 3 < len)
        payload |= (*(p + i + 3) << 24);
      dsi_write(DSI_GEN_PD_CFG, payload);
    }

  /* 等待 PHY 停止状态 */

  ret = dsi_wait_stop_state_c();
  if (ret < 0)
    {
      return ret;
    }

  /* 触发命令发送 */

  dsi_set_bits(DSI_CMD_MODE_CFG, DSI_CMD_MODE_CFG_GEN_SW_0P);
  up_udelay(100);

  return OK;
}

/****************************************************************************
 * Name: d13x_dsi_init
 *
 * Description:
 *   初始化 MIPI DSI 控制器
 *
 ****************************************************************************/

int d13x_dsi_init(uint32_t pixel_clock)
{
  int ret;

  iinfo("Initializing MIPI DSI...\n");

  /* 使能控制器 */

  d13x_dsi_enable();

  /* 配置时钟分频 */

  uint32_t format_div = 24;  /* RGB888 */
  uint32_t lane_num = 4;
  uint32_t sclk_rate = pixel_clock * format_div / lane_num;
  uint32_t div = sclk_rate / 8 / DSI_LP_RATE;
  uint32_t val = dsi_read(DSI_CLK_CFG);
  val &= ~(DSI_CLK_CFG_LP_DIV_MASK);
  val |= DSI_CLK_CFG_LP_DIV(div);
  dsi_write(DSI_CLK_CFG, val);

  iinfo("DSI clock: pixel=%dHz, sclk=%dHz, div=%d\n",
        pixel_clock, sclk_rate, div);

  /* 配置包 */

  dsi_set_bits(DSI_CTL, DSI_CTL_PKG_CFG_CRC_RX_EN | DSI_CTL_PKG_CFG_ECC_RX_EN);

  /* 配置 LP 传输时间 */

  dsi_write(DSI_DPI_LPTX_TIME, (64 << 16) | 64);

  /* 配置超时 */

  dsi_write(DSI_TO_CNT_CFG, 0);

  /* 配置命令模式 */

  val = BIT(24) | BIT(19) | BIT(18) | BIT(17) | BIT(16) |
        BIT(14) | BIT(13) | BIT(12) | BIT(11) | BIT(10) | BIT(9) | BIT(8);
  dsi_write(DSI_CMD_MODE_CFG, val);

  /* 配置通道 */

  dsi_write(DSI_LANE_CFG, 0x3210);

  /* 初始化 PHY */

  ret = d13x_dsi_phy_init(pixel_clock);
  if (ret < 0)
    {
      ierr("DSI PHY init failed: %d\n", ret);
      return ret;
    }

  /* 使能高速时钟 */

  ret = d13x_dsi_hs_clk_enable(true);
  if (ret < 0)
    {
      ierr("DSI HS clock enable failed: %d\n", ret);
      return ret;
    }

  iinfo("MIPI DSI initialized, pixel clock=%d Hz\n", pixel_clock);
  return OK;
}

