  putreg32(val, gpio_base + BACKLIGHT_GPIO_PIN * 0x4 + 0x80);

  /* 配置为输出模式 */

  val = getreg32(gpio_base + 0x40);  /* GPIO_DIR 寄存器 */
  val |= (1 << BACKLIGHT_GPIO_PIN);
  putreg32(val, gpio_base + 0x40);

  iinfo("Backlight GPIO P%c.%d initialized\n",
        'A' + BACKLIGHT_GPIO_GROUP, BACKLIGHT_GPIO_PIN);
}

