/****************************************************************************
 * Name: d13x_lcd_reset
 *
 * Description:
 *   LCD 硬件复位序列 (来源: luban-lite panel_dsi_xm91080.c)
 *
 ****************************************************************************/

static void d13x_lcd_reset(void)
{
  uint32_t gpio_base = D13X_GPIO_BASE + LCD_RST_GPIO_GROUP * 0x100;

  /* 复位序列: HIGH -> LOW -> HIGH */

  /* 设置为 HIGH */

  if (LCD_RST_ACTIVE_LOW)
    {
      putreg32((1 << LCD_RST_GPIO_PIN), gpio_base + 0x30);  /* GPIO_SET */
    }
  else
    {
      putreg32((1 << LCD_RST_GPIO_PIN), gpio_base + 0x34);  /* GPIO_CLR */
    }
  up_mdelay(10);

  /* 设置为 LOW */

  if (LCD_RST_ACTIVE_LOW)
    {
      putreg32((1 << LCD_RST_GPIO_PIN), gpio_base + 0x34);  /* GPIO_CLR */
    }
  else
    {
      putreg32((1 << LCD_RST_GPIO_PIN), gpio_base + 0x30);  /* GPIO_SET */
    }
  up_mdelay(10);

  /* 设置为 HIGH */

  if (LCD_RST_ACTIVE_LOW)
    {
      putreg32((1 << LCD_RST_GPIO_PIN), gpio_base + 0x30);  /* GPIO_SET */
    }
  else
    {
      putreg32((1 << LCD_RST_GPIO_PIN), gpio_base + 0x34);  /* GPIO_CLR */
    }
  up_mdelay(20);

  iinfo("LCD reset completed\n");
}

