/****************************************************************************
 * Name: panel_send_dcs_cmd
 *
 * Description:
 *   发送 DCS 命令
 *
 ****************************************************************************/

static int panel_send_dcs_cmd(uint8_t cmd, uint8_t *params, uint32_t len)
{
  uint8_t buf[16];

  buf[0] = 0x15;  /* DCS Short Write */
  buf[1] = cmd;

  for (uint32_t i = 0; i < len && i < 14; i++)
    {
      buf[2 + i] = params[i];
    }

  return panel_dsi_write_cmd(buf, 2 + len);
}

input.new_string:
/****************************************************************************
 * Name: panel_send_dcs_cmd
 *
 * Description:
 *   发送 DCS 命令 (来源: luban-lite dsi_cmd_wr)
 *
 ****************************************************************************/

static int panel_send_dcs_cmd(uint8_t cmd, uint8_t *params, uint32_t len)
{
  uint32_t dt;

  if (len == 0)
    {
      /* DCS 命令, 无参数 */

      dt = DSI_DT_DCS_WR_P0;
      return d13x_dsi_cmd_wr(dt, &cmd, 1);
    }
  else if (len == 1)
    {
      /* DCS 命令, 1个参数 */

      dt = DSI_DT_DCS_WR_P1;
      uint8_t buf[2] = {cmd, params[0]};
      return d13x_dsi_cmd_wr(dt, buf, 2);
    }
  else
    {
      /* DCS 命令, 多个参数 */

      dt = DSI_DT_DCS_LONG_WR;
      uint8_t buf[17];
      buf[0] = cmd;
      for (uint32_t i = 0; i < len && i < 16; i++)
        {
          buf[1 + i] = params[i];
        }
      return d13x_dsi_cmd_wr(dt, buf, 1 + len);
    }
}

