/****************************************************************************
 * Name: d13x_i2c1_pinmux_init
 *
 * Description:
 *   初始化 I2C1 引脚 (PA2=SCL, PA3=SDA)
 *   来源: D13x pinmux (function 4 = I2C1)
 *
 ****************************************************************************/

static void d13x_i2c1_pinmux_init(void)
{
  uint32_t val;

  /* PA.2 (I2C1_SCL): function 4 */

  val = getreg32(D13X_GPIO_PIN_CFG(0, 2));  /* PA 组=0, pin=2 */
  val &= ~(PIN_CFG_FUN_MASK << PIN_CFG_FUN_SHIFT);
  val |= (GPIO_FUN_I2C1 << PIN_CFG_FUN_SHIFT);
  putreg32(val, D13X_GPIO_PIN_CFG(0, 2));

  /* PA.3 (I2C1_SDA): function 4 */

  val = getreg32(D13X_GPIO_PIN_CFG(0, 3));  /* PA 组=0, pin=3 */
  val &= ~(PIN_CFG_FUN_MASK << PIN_CFG_FUN_SHIFT);
  val |= (GPIO_FUN_I2C1 << PIN_CFG_FUN_SHIFT);
  putreg32(val, D13X_GPIO_PIN_CFG(0, 3));

  iinfo("I2C1 pins (PA2/PA3) configured\n");
}

