  /* 11. SCLK 和 PIX 时钟配置 (来源: luban-lite drv_dsi.c)
   *     SCLK = PLL_FRA2 / 2 = 614.4 / 2 = 307.2MHz
   *     PIX = pixel_clock = 51.2MHz
   *     CLK_SCLK: src=PLL_FRA2, div=2
   *     CLK_PIX: src=SCLK, div=6
   */

  /* CLK_SCLK: PLL_FRA2 / 2 */

  reg = getreg32(D13X_CMU_BASE + 0x010);  /* CMU_CLK_SCLK */
  reg &= ~(0x3 << 8);  /* 清除源选择 */
  reg |= (0x2 << 8);   /* 源 = PLL_FRA2 */
  reg &= ~(0x3 << 0);  /* 清除分频 */
  reg |= (0x1 << 0);   /* 分频 = 2 */
  putreg32(reg, D13X_CMU_BASE + 0x010);

  /* CLK_PIX: SCLK / 6 */

  reg = getreg32(D13X_CMU_BASE + 0x014);  /* CMU_CLK_PIX */
  reg &= ~(0x3 << 8);  /* 清除源选择 */
  reg |= (0x3 << 8);   /* 源 = SCLK */
  reg &= ~(0x3 << 0);  /* 清除分频 */
  reg |= (0x5 << 0);   /* 分频 = 6 */
  putreg32(reg, D13X_CMU_BASE + 0x014);
